      "inputs": {
        "script": "const fields = ($vars.extractFormFields.output && $vars.extractFormFields.output.ExtractionResult && $vars.extractFormFields.output.ExtractionResult.ResultsDocument && $vars.extractFormFields.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractFormFields.output.ExtractionResult.ResultsDocument.Fields : [];\nconst getValue = (name) => { const f = fields.find(f => f.FieldName === name); return f ? (f.Values && f.Values[0]) : null; };\nreturn { borrowerName: getValue('Borrower Name'), propertyAddress: getValue('Subject Property Address'), loanAmount: getValue('Loan Amount'), fieldCount: fields.length };"
      },
